function fullName(db: ReturnType<typeof useStore>['db'], id: string) { return db.profiles.find(p => p.id === id)?.name || 'Registered patient' }
function activePatientIds(db: ReturnType<typeof useStore>['db'], doctorId: string) {
  return Array.from(new Set(db.grants.filter(g => g.doctorId === doctorId && activeGrantFor(db, g.patientId, doctorId)).map(g => g.patientId)))
}
function currentScopeText(db: ReturnType<typeof useStore>['db'], patientId: string, doctorId: string) {
  const grant = activeGrantFor(db, patientId, doctorId)
  if (!grant) return 'No active grant'
  if (grant.scope.type === 'all') return 'All records & health summary'
  if (grant.scope.type === 'categories') return grant.scope.categories.map(c => CATEGORY_LABELS[c]).join(', ')
  return `${grant.scope.recordIds.length} selected records`
}
function makePrintableDoctorSummary(patientName: string, patientId: string, records: MedicalRecord[], conditions: { condition: string; confirmed: boolean; recordedBy: string }[], medications: Medication[], allergies: { allergen: string; reaction?: string; confirmed: boolean }[], surgeries: Surgery[]) {
  const esc = (value: string) => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char] || char))
  const list = (lines: string[]) => lines.length ? lines.map(x => `<li>${x}</li>`).join('') : '<li>No information shared in this scope.</li>'
  const labs = records.flatMap(r => (r.labResults || []).map(l => `<li>${esc(l.test)} · ${esc(l.value)} ${esc(l.unit)} · ${fmtDate(r.date)} · Source: ${esc(r.title)}</li>`))
  const procedures = surgeries.map(s => `${esc(s.procedure)} · ${fmtDate(s.date)} · ${esc(s.hospital || 'provider not recorded')}`)
  const html = `<!doctype html><html><head><title>Authorized patient summary</title><meta charset="utf-8"><style>body{font:15px/1.5 Arial,sans-serif;color:#152f47;max-width:780px;margin:42px auto;padding:0 28px}h1{margin:4px 0}h2{font-size:16px;border-bottom:1px solid #dce6ed;padding-bottom:6px;margin-top:25px}.meta{font-size:13px;color:#66798c}.note{padding:12px;background:#fff5df;border:1px solid #eedaaa;border-radius:8px;margin:20px 0}@media print{body{margin:18mm auto}}</style></head><body><div class="meta">MEDIVAULT · AUTHORIZED DEMO EXPORT · ${new Date().toLocaleDateString('en-IN')}</div><h1>${esc(patientName)}</h1><div class="meta">Patient ID · ${esc(patientId)} · Generated from records currently shared with this clinician</div><div class="note">Fictional hackathon demo. Verify every entry against source records and with the patient. This is not a diagnosis, treatment recommendation, or legally valid clinical document.</div><h2>Recorded conditions</h2><ul>${list(conditions.map(c => `${esc(c.condition)} — ${c.confirmed ? 'clinician-confirmed' : 'patient-reported'} (${esc(c.recordedBy)})`))}</ul><h2>Current medications</h2><ul>${list(medications.map(m => `${esc(m.name)} · ${esc(m.dose || 'dose not recorded')} · ${esc(m.status)} · recorded ${fmtDate(m.startDate)}`))}</ul><h2>Recorded allergies</h2><ul>${list(allergies.map(a => `${esc(a.allergen)} — ${esc(a.reaction || 'reaction not recorded')} (${a.confirmed ? 'confirmed' : 'patient-reported'})`))}</ul><h2>Past procedures</h2><ul>${list(procedures)}</ul><h2>Recent test results</h2><ul>${list(labs)}</ul><h2>Shared records</h2><ul>${list(records.map(r => `${fmtDate(r.date)} · ${esc(r.title)} · ${esc(r.provider)}`))}</ul><p class="meta">Source dates and document titles are shown where available. AI-style summary in MediVault demo is deterministic and requires clinician verification.</p><script>window.onload=()=>setTimeout(()=>window.print(),250)</script></body></html>`
  const win = window.open('', '_blank', 'width=780,height=860')
  if (!win) return false
  win.document.open(); win.document.write(html); win.document.close(); return true
}

function DoctorMetric({ icon, label, value, detail, tone, onClick }: { icon: React.ReactNode; label: string; value: number | string; detail: string; tone: string; onClick?: () => void }) {
  return <button className={`health-metric metric-${tone}`} onClick={onClick}><span className="metric-icon">{icon}</span><span className="metric-copy"><small>{label}</small><strong>{value}</strong><span>{detail}</span></span><ChevronRight className="metric-arrow" size={16} /></button>
}

export function DoctorOverview({ onNavigate }: { onNavigate: (page: any) => void }) {
  const { db, currentUser } = useStore()
  if (!currentUser) return null
  const patientIds = activePatientIds(db, currentUser.id)
  const pending = db.accessRequests.filter(r => r.doctorId === currentUser.id && r.status === 'pending')
  const shareHistory = db.grants.filter(g => g.doctorId === currentUser.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 4)
  const appointments = db.appointments.filter(a => a.doctorId === currentUser.id && ['proposed', 'accepted'].includes(a.status)).sort((a, b) => a.dateTime.localeCompare(b.dateTime))
  const recentViews = db.recentViews.filter(v => v.doctorId === currentUser.id && patientIds.includes(v.patientId)).sort((a, b) => b.at.localeCompare(a.at)).slice(0, 3)
  const doctorMeta = db.doctors.find(d => d.profileId === currentUser.id)
  return <div className="page-stack"><div className="doctor-welcome"><div><div className="welcome-eyebrow"><span className="live-dot" /> CLINICAL WORKSPACE · DEMO DATA</div><h1>Good {new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 17 ? 'afternoon' : 'evening'}, {currentUser.name.replace('Dr. ', '')}</h1><p>Review patient records only when an active share covers them.</p><div className="doctor-credential"><Stethoscope size={14} /> {doctorMeta?.specialization || 'Doctor'} <i /> {doctorMeta?.hospital || 'Clinic not set'}</div></div><div className="doctor-welcome-icon"><Stethoscope size={31} /></div></div>
    <div className="metric-grid doctor-metric-grid"><DoctorMetric icon={<UsersRound size={20} />} label="ACTIVE CONSENTS" value={patientIds.length} detail="Patients who granted access" tone="blue" onClick={() => onNavigate('patients')} /><DoctorMetric icon={<FileHeart size={20} />} label="RECENT SHARES" value={shareHistory.filter(g => !isExpired(g.expiresAt) && g.status === 'active').length} detail="Active record permissions" tone="teal" onClick={() => onNavigate('patients')} /><DoctorMetric icon={<CalendarDays size={20} />} label="UPCOMING VISITS" value={appointments.length} detail="Simulated clinic schedule" tone="purple" onClick={() => onNavigate('appointments')} /><DoctorMetric icon={<HeartHandshake size={20} />} label="PENDING REQUESTS" value={pending.length} detail="Awaiting patient response" tone="amber" onClick={() => onNavigate('requests')} /></div>
    <div className="doctor-dashboard-grid"><section className="panel doctor-share-panel"><div className="panel-heading"><div><div className="eyebrow">CONSENT-BASED WORKLIST</div><h2>Recently shared with you</h2></div><button className="text-action" onClick={() => onNavigate('patients')}>All authorized <ArrowRight size={14} /></button></div>{patientIds.length ? <div className="doctor-patient-list">{shareHistory.filter(g => patientIds.includes(g.patientId)).map(grant => <button className="doctor-patient-row" key={grant.id} onClick={() => onNavigate('patients')}><span className="patient-row-avatar">{fullName(db, grant.patientId).split(' ').map(s => s[0]).slice(0, 2).join('')}</span><span><b>{fullName(db, grant.patientId)}</b><small>{db.patients.find(p => p.profileId === grant.patientId)?.patientId} · {currentScopeText(db, grant.patientId, currentUser.id)}</small></span><span className="patient-row-expiry"><small>EXPIRES</small>{fmtDate(grant.expiresAt)}</span><ChevronRight size={15} /></button>)}</div> : <EmptyState icon={<LockKeyhole size={23} />} title="No active patient shares" description="Patients appear here only after they grant access to your account." action={<Button size="sm" variant="outline" onClick={() => onNavigate('requests')}>Request access</Button>} />}</section>
      <section className="panel doctor-requests-panel"><div className="panel-heading"><div><div className="eyebrow">PATIENT CONSENT</div><h2>Access requests</h2></div><Badge tone={pending.length ? 'amber' : 'neutral'}>{pending.length} pending</Badge></div>{pending.length ? pending.map(r => <div className="doctor-outgoing-request" key={r.id}><span className="pending-pulse" /><div><b>Patient request pending</b><small>Sent {fmtDateTime(r.createdAt)} · No records visible</small></div><Badge tone="amber">Pending</Badge></div>) : <div className="inline-empty"><CheckCircle2 size={17} /><span><b>No requests waiting</b><small>Patient consent is required before record access.</small></span></div>}<button className="panel-link-button" onClick={() => onNavigate('requests')}>Manage requests <ArrowRight size={14} /></button></section></div>
    <div className="doctor-dashboard-grid lower-dashboard"><section className="panel doctor-appointment-panel"><div className="panel-heading"><div><div className="eyebrow">SIMULATED CLINIC SCHEDULE</div><h2>Upcoming appointments</h2></div><button className="text-action" onClick={() => onNavigate('appointments')}>View schedule <ArrowRight size={14} /></button></div>{appointments.length ? appointments.slice(0, 3).map(a => <DoctorAppointmentRow key={a.id} appointment={a} />) : <div className="inline-empty"><CalendarDays size={17} /><span><b>No upcoming appointments</b><small>Appointments show for patients connected to your demo account.</small></span></div>}</section><section className="panel recently-viewed-panel"><div className="panel-heading"><div><div className="eyebrow">YOUR RECENT WORK</div><h2>Recently viewed</h2></div><Activity size={17} className="subtle-icon" /></div>{recentViews.length ? recentViews.map(view => <button className="recent-patient-row" key={`${view.patientId}-${view.at}`} onClick={() => onNavigate('patients')}><span className="patient-row-avatar">{fullName(db, view.patientId).split(' ').map(s => s[0]).slice(0, 2).join('')}</span><span><b>{fullName(db, view.patientId)}</b><small>Opened {fmtDateTime(view.at)}</small></span><ArrowUpRight size={15} /></button>) : <div className="inline-empty"><UserRound size={17} /><span><b>No recently viewed patients</b><small>Authorized patient workspaces will appear here.</small></span></div>}</section></div>
    <div className="doctor-guidance"><ShieldCheck size={15} /><span>Least-privilege access is active. Expired and revoked grants are rejected on every record retrieval in this demo.</span><button onClick={() => onNavigate('requests')}>Request access <ArrowRight size={14} /></button></div><div className="fictional-notice"><Info size={14} /> Patient data is simulated and stored locally in this browser. Do not use real medical information.</div></div>
}

function DoctorAppointmentRow({ appointment }: { appointment: Appointment }) {
  const { db } = useStore()
  const patient = db.patients.find(p => p.profileId === appointment.patientId)
  return <div className="doctor-appointment-row"><span className="mini-date"><b>{new Date(appointment.dateTime).getDate()}</b><small>{new Date(appointment.dateTime).toLocaleDateString('en-IN', { month: 'short' })}</small></span><span><b>{fullName(db, appointment.patientId)}</b><small>{appointment.clinic} · {new Date(appointment.dateTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })} · {patient?.patientId}</small></span><Badge tone={appointment.status === 'accepted' ? 'green' : 'amber'}>{appointment.status}</Badge></div>
}

export function DoctorPatientsPage({ globalSearch = '', clearGlobalSearch }: { globalSearch?: string; clearGlobalSearch?: () => void }) {
  const { db, currentUser, mutate, addAudit } = useStore()
  const toast = useToast()
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [search, setSearch] = useState(globalSearch)
  useEffect(() => { if (globalSearch) setSearch(globalSearch) }, [globalSearch])
  const [scopeFilter, setScopeFilter] = useState('all')
  if (!currentUser) return null
  const patientIds = activePatientIds(db, currentUser.id)
  if (selectedId) return <ClinicalWorkspace patientId={selectedId} onBack={() => setSelectedId(null)} />
  const patients = patientIds.map(id => ({ profile: db.profiles.find(p => p.id === id)!, patient: db.patients.find(p => p.profileId === id), grant: activeGrantFor(db, id, currentUser.id)! })).filter(row => row.profile && row.grant)
    .filter(row => `${row.profile.name} ${row.patient?.patientId} ${row.grant.scope.type}`.toLowerCase().includes(search.toLowerCase()))
    .filter(row => scopeFilter === 'any' || row.grant.scope.type === scopeFilter)
    .sort((a, b) => a.profile.name.localeCompare(b.profile.name))
  const openWorkspace = (patientId: string) => {
    try {
      const records = readAuthorizedRecords(db, currentUser.id, patientId)
      if (!activeGrantFor(db, patientId, currentUser.id)) throw new AccessDeniedError('Access expired.')
      mutate(prev => ({ ...prev, recentViews: [{ doctorId: currentUser.id, patientId, at: new Date().toISOString() }, ...prev.recentViews.filter(v => !(v.doctorId === currentUser.id && v.patientId === patientId))].slice(0, 30) }))
      addAudit('record_view', `Opened an authorized clinical workspace (${records.length} shared records).`, patientId)
      setSelectedId(patientId)
    } catch (error) { toast(error instanceof Error ? error.message : 'Access denied.', 'error') }
  }
  const setGlobal = (value: string) => { setSearch(value); if (globalSearch && clearGlobalSearch) clearGlobalSearch() }
  return <div className="page-stack"><PageTitle eyebrow="ACTIVE CONSENT ONLY" title="Authorized patients" description="Only patients with a current grant to your account appear in this workspace." action={<Badge tone="green"><i className="status-dot" /> {patientIds.length} active</Badge>} /><section className="panel authorized-panel"><div className="record-toolbar"><div className="record-search"><Search size={16} /><input value={search} onChange={e => setGlobal(e.target.value)} placeholder="Search name or patient ID…" />{search && <button aria-label="Clear search" onClick={() => setGlobal('')}><X size={14} /></button>}</div><label className="scope-filter"><Filter size={14} /><select value={scopeFilter} onChange={e => setScopeFilter(e.target.value)}><option value="any">All access scopes</option><option value="all">Full history</option><option value="records">Selected records</option><option value="categories">Selected categories</option></select></label></div>{patients.length ? <div className="authorized-patient-list">{patients.map(({ profile, patient, grant }) => {
    const records = readAuthorizedRecords(db, currentUser.id, profile.id)
    const allData = grantCoversAllHealthData(grant)
    const activeMeds = allData ? db.medications.filter(m => m.patientId === profile.id && m.status === 'active') : []
    const allergies = allData ? db.allergies.filter(a => a.patientId === profile.id) : []
    const conditions = allData ? db.conditions.filter(c => c.patientId === profile.id) : []
    const latest = records[0]
    return <article className="authorized-patient-card" key={profile.id}><div className="authorized-card-head"><div className="patient-avatar-lg">{profile.name.split(' ').map(s => s[0]).slice(0, 2).join('')}</div><div className="authorized-name"><h3>{profile.name}</h3><span>Patient ID · {patient?.patientId}</span></div><Badge tone="green"><CheckCircle2 size={12} /> Active consent</Badge><button className="icon-button" onClick={() => openWorkspace(profile.id)} aria-label={`Open ${profile.name} workspace`}><ArrowUpRight size={17} /></button></div><div className="authorized-context-grid"><div><small>SHARED RECORDS</small><b><FileHeart size={14} /> {records.length} documents</b></div><div><small>ACCESS SCOPE</small><b><LockKeyhole size={14} /> {currentScopeText(db, profile.id, currentUser.id)}</b></div><div><small>EXPIRES</small><b><Clock3 size={14} /> {fmtDateTime(grant.expiresAt)}</b></div><div><small>MOST RECENT VISIT / RECORD</small><b><CalendarDays size={14} /> {latest ? `${fmtDate(latest.date)} · ${latest.title}` : 'No shared records yet'}</b></div></div>{allData ? <div className="authorized-health-summary"><div><small>RECORDED CONDITIONS</small><span>{conditions.length ? conditions.map(c => c.condition).join(', ') : 'None recorded'}</span></div><div><small>CURRENT MEDICATIONS</small><span>{activeMeds.length ? activeMeds.map(m => `${m.name} ${m.dose || '(dose missing)'}`).join(' · ') : 'None recorded'}</span></div><div><small>ALLERGIES</small><span>{allergies.length ? allergies.map(a => `${a.allergen} — ${a.reaction || 'reaction not recorded'}`).join(' · ') : 'None recorded; allergy status not confirmed'}</span></div></div> : <div className="scope-only-note"><ShieldCheck size={14} /> Health summary hidden. This grant covers selected documents only.</div>}<div className="authorized-card-footer"><span>{latest ? <>Most recent: <b>{latest.title}</b></> : 'No shared document is currently in scope.'}</span><Button size="sm" onClick={() => openWorkspace(profile.id)}>Open workspace <ArrowRight size={14} /></Button></div></article>
  })}</div> : patientIds.length ? <EmptyState icon={<Search size={23} />} title="No matching authorized patients" description="Try another name, ID or access scope filter." /> : <EmptyState icon={<LockKeyhole size={23} />} title="No active patient consent" description="A patient appears only after granting your account an active, time-limited access permission." action={<Button variant="outline" onClick={() => window.dispatchEvent(new CustomEvent('medivault:navigate', { detail: 'requests' }))}>Request access</Button>} />}</section><div className="fictional-notice"><Info size={14} /> This list is not a global patient directory. Data shown is fictional and consent-scoped.</div></div>
}

function AccessDenied({ onBack }: { onBack: () => void }) {
  return <div className="access-denied-screen"><div className="denied-icon"><ShieldAlert size={26} /></div><div className="eyebrow">CONSENT REQUIRED</div><h2>Access denied</h2><p>This patient’s grant is missing, expired or has been revoked. Protected records cannot be retrieved without current patient authorization.</p><div className="denied-actions"><Button variant="outline" onClick={onBack}><ArrowLeft size={15} /> Back to authorized patients</Button><span><LockKeyhole size={13} /> No record data was loaded</span></div></div>
}

type WorkspaceTab = 'overview' | 'timeline' | 'records' | 'labs' | 'medications' | 'allergies' | 'notes' | 'permissions'
function ClinicalWorkspace({ patientId, onBack }: { patientId: string; onBack: () => void }) {
  const { db, currentUser, getActiveGrant, getDoctorRecords, mutate, addAudit } = useStore()
  const toast = useToast()
  const [tab, setTab] = useState<WorkspaceTab>('overview')
  const [recordSearch, setRecordSearch] = useState('')
  const [recordPreview, setRecordPreview] = useState<MedicalRecord | null>(null)
  const [noteOpen, setNoteOpen] = useState(false)
  const [diagnosisOpen, setDiagnosisOpen] = useState(false)
  const [prescriptionOpen, setPrescriptionOpen] = useState(false)
  const [summaryOpen, setSummaryOpen] = useState(false)
  const [compareTest, setCompareTest] = useState('')
  const [saving, setSaving] = useState(false)
  if (!currentUser) return null
  const grant = getActiveGrant(patientId, currentUser.id)
  const patient = db.patients.find(p => p.profileId === patientId)
  const profile = db.profiles.find(p => p.id === patientId)
  let records: MedicalRecord[] = []
  try { records = getDoctorRecords(patientId) } catch { return <AccessDenied onBack={onBack} /> }
  if (!grant || !profile) return <AccessDenied onBack={onBack} />
  const fullSummary = grantCoversAllHealthData(grant)
  const conditions = fullSummary ? db.conditions.filter(c => c.patientId === patientId) : []
  const allergies = fullSummary ? db.allergies.filter(a => a.patientId === patientId) : []
  const medications = fullSummary ? db.medications.filter(m => m.patientId === patientId) : []
  const surgeries = fullSummary ? db.surgeries.filter(s => s.patientId === patientId) : []
  const ownedNotes = db.notes.filter(n => n.patientId === patientId && n.doctorId === currentUser.id).sort((a, b) => b.visitDate.localeCompare(a.visitDate))
  const allNotes = db.notes.filter(n => n.patientId === patientId).sort((a, b) => b.visitDate.localeCompare(a.visitDate))
  const tests = Array.from(new Map(records.flatMap(r => (r.labResults || []).map(l => [normalize(l.test), l.test] as const)).map(pair => pair)).values())
  const selectedTest = compareTest || tests[0] || ''
  const labRows = records.flatMap(record => (record.labResults || []).filter(l => normalize(l.test) === normalize(selectedTest)).map(l => ({ ...l, date: record.date, title: record.title, provider: record.provider, recordId: record.id }))).sort((a, b) => a.date.localeCompare(b.date))
  const labUnits = Array.from(new Set(labRows.map(r => r.unit)))
  const chartReady = labRows.length > 1 && labRows.every(r => typeof r.numericValue === 'number') && labUnits.length === 1
  const accessibleRows = records.filter(r => `${r.title} ${r.provider} ${r.notes || ''} ${r.tags.join(' ')}`.toLowerCase().includes(recordSearch.toLowerCase())).sort((a, b) => b.date.localeCompare(a.date))
  const previousSameTest = (record: MedicalRecord, testName: string) => records.filter(r => r.date < record.date && r.labResults?.some(l => normalize(l.test) === normalize(testName))).sort((a, b) => b.date.localeCompare(a.date))[0]
  const duplicateIds = new Set(records.filter(record => records.some(other => other.id !== record.id && Math.abs(new Date(other.date).getTime() - new Date(record.date).getTime()) < 3 * 86400000 && normalize(other.provider) === normalize(record.provider) && record.labResults?.some(lab => other.labResults?.some(o => normalize(o.test) === normalize(lab.test))))).map(r => r.id))
  const tabList: [WorkspaceTab, string][] = [['overview','Overview'],['timeline','Medical timeline'],['records','Records'],['labs','Lab results'],['medications','Medications'],['allergies','Allergies'],['notes','Clinical notes'],['permissions','Access permissions']]
  const previewRecord = (record: MedicalRecord) => {
    try { readAuthorizedRecords(db, currentUser.id, patientId).find(r => r.id === record.id) || (() => { throw new AccessDeniedError('Record is not within this grant.') })(); setRecordPreview(record); addAudit('record_view', `Previewed shared record: ${record.title}.`, patientId) }
    catch (error) { toast(error instanceof Error ? error.message : 'Access denied.', 'error') }
  }
  const saveNote = (data: Omit<ConsultationNote, 'id' | 'patientId' | 'doctorId' | 'createdAt'>) => {
    if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — patient consent is no longer active.', 'error')
    const note: ConsultationNote = { ...data, id: uid('note'), patientId, doctorId: currentUser.id, createdAt: new Date().toISOString() }
    mutate(prev => ({ ...prev, notes: [note, ...prev.notes] }))
    addAudit('note_created', 'Added a consultation note to an authorized patient workspace.', patientId)
    toast('Consultation note saved with your authorship and timestamp.'); setNoteOpen(false)
  }
  const saveDiagnosis = (condition: string, date: string, note: string) => {
    if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — patient consent is no longer active.', 'error')
    mutate(prev => ({ ...prev, diagnoses: [{ id: uid('diagnosis'), patientId, doctorId: currentUser.id, condition, date, confirmed: true, notes: note }, ...prev.diagnoses] }))
    addAudit('note_created', 'Added a clinician-authored diagnosis entry.', patientId); toast('Diagnosis entry saved with clinician authorship.'); setDiagnosisOpen(false)
  }
  const saveDraft = (draft: { medicine: string; dose: string; frequency: string; instructions: string }) => {
    if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — patient consent is no longer active.', 'error')
    mutate(prev => ({ ...prev, prescriptionDrafts: [{ id: uid('rx-draft'), patientId, doctorId: currentUser.id, ...draft, createdAt: new Date().toISOString(), status: 'draft' }, ...prev.prescriptionDrafts] }))
    addAudit('note_created', 'Created a prescription draft (not legally valid).', patientId); toast('Prescription saved as a clearly labeled draft.'); setPrescriptionOpen(false)
  }
  const recordDownload = (record: MedicalRecord) => {
    try { readAuthorizedRecords(db, currentUser.id, patientId).find(r => r.id === record.id) || (() => { throw new AccessDeniedError('Access denied.') })(); downloadRecord(record); addAudit('record_download', `Downloaded shared record: ${record.title}.`, patientId); toast('Authorized record downloaded.') }
    catch (error) { toast(error instanceof Error ? error.message : 'Access denied.', 'error') }
  }
  const markReview = (medication: Medication, outcome: 'reviewed' | 'continued' | 'changed' | 'discontinued') => {
    if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — consent is no longer active.', 'error')
    mutate(prev => ({ ...prev, medReviews: [{ medicationId: medication.id, doctorId: currentUser.id, outcome, reviewedAt: new Date().toISOString() }, ...prev.medReviews.filter(r => !(r.medicationId === medication.id && r.doctorId === currentUser.id))] }))
    toast(`${medication.name} review saved.`)
  }
  const exportSummary = () => {
    if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — consent is no longer active.', 'error')
    if (!makePrintableDoctorSummary(profile.name, patient?.patientId || '—', records, conditions, medications.filter(m => m.status === 'active'), allergies, surgeries)) return toast('Pop-up blocked. Allow pop-ups to export this summary.', 'error')
    addAudit('summary_generated', 'Exported a summary from currently authorized patient records.', patientId)
  }
  const generateSummary = () => { if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied.', 'error'); setSummaryOpen(true); addAudit('summary_generated', 'Generated a deterministic summary from authorized demo records.', patientId) }
  const workspaceAction = (action: () => void) => { if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — this patient’s access has expired or been revoked.', 'error'); action() }

  return <div className="page-stack clinical-workspace"><div className="workspace-back-row"><button className="back-link" onClick={onBack}><ArrowLeft size={15} /> Back to authorized patients</button><span className="access-live-label"><i className="status-dot" /> Active patient consent</span></div><div className="workspace-patient-head"><div className="workspace-patient-identity"><div className="patient-avatar-lg">{profile.name.split(' ').map(s => s[0]).slice(0,2).join('')}</div><div><div className="eyebrow">AUTHORIZED CLINICAL WORKSPACE</div><h1>{profile.name}</h1><p>Patient ID · {patient?.patientId || '—'} <i /> Consent expires {fmtDateTime(grant.expiresAt)}</p></div></div><div className="workspace-actions"><Button variant="outline" size="sm" onClick={() => workspaceAction(generateSummary)}><Activity size={14} /> Generate medical summary</Button><Button size="sm" onClick={() => workspaceAction(() => setNoteOpen(true))}><Plus size={15} /> Add consultation note</Button><button className="icon-button" aria-label="More actions" onClick={() => setTab('permissions')}><MoreHorizontal size={17} /></button></div></div><nav className="workspace-tabs">{tabList.map(([id, label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => { if (!getActiveGrant(patientId, currentUser.id)) return toast('Access denied — the patient’s grant is no longer active.', 'error'); setTab(id) }}>{label}{id === 'records' && <span>{records.length}</span>}</button>)}</nav>
    {tab === 'overview' && <div className="workspace-tab-content"><div className="workspace-overview-grid"><section className="panel workspace-overview-main"><div className="panel-heading"><div><div className="eyebrow">SHARED RECORDS</div><h2>Patient overview</h2></div><Badge tone={fullSummary ? 'green' : 'blue'}>{fullSummary ? 'Full health summary' : 'Scoped access'}</Badge></div>{fullSummary ? <><div className="workspace-summary-metrics"><div><small>RECORDS IN SCOPE</small><b>{records.length}</b></div><div><small>ACTIVE MEDICATIONS</small><b>{medications.filter(m => m.status === 'active').length}</b></div><div><small>RECORDED ALLERGIES</small><b>{allergies.length}</b></div><div><small>RECORDED CONDITIONS</small><b>{conditions.length}</b></div></div><div className="workspace-info-columns"><div><h3>Recorded conditions</h3>{conditions.length ? conditions.map(c => <div className="workspace-info-row" key={c.id}><span className="condition-bullet" /><span><b>{c.condition}</b><small>{c.confirmed ? `Clinician-confirmed · ${c.recordedBy}` : 'Patient-reported · verify'}</small></span></div>) : <p className="muted-copy">None recorded; absence not clinically confirmed.</p>}</div><div><h3>Recorded allergies</h3>{allergies.length ? allergies.map(a => <div className="workspace-info-row" key={a.id}><AlertCircle size={15} className="allergy-symbol" /><span><b>{a.allergen}</b><small>{a.reaction || 'Reaction not recorded'} · {a.confirmed ? 'confirmed' : 'patient-reported'}</small></span></div>) : <p className="muted-copy">No allergy record in the shared profile.</p>}</div></div></> : <div className="scoped-access-banner"><LockKeyhole size={18} /><div><b>Limited access is active</b><p>Only selected records are available. The patient’s profile, medications, conditions and allergies are hidden because this grant does not include the full health summary.</p><span>In-scope records: {records.length} · {currentScopeText(db, patientId, currentUser.id)}</span></div></div>}</section><section className="panel workspace-recent-panel"><div className="panel-heading"><div><div className="eyebrow">LATEST IN SCOPE</div><h2>Recent records</h2></div><button className="text-action" onClick={() => setTab('records')}>All records <ArrowRight size={14} /></button></div>{records.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(r => <button className="workspace-record-row" key={r.id} onClick={() => previewRecord(r)}><span className="record-type-icon type-blood_test"><FileText size={15} /></span><span><b>{r.title}</b><small>{fmtDate(r.date)} · {r.provider}</small></span><ChevronRight size={15} /></button>)}{!records.length && <div className="quiet-empty">No records included in this share.</div>}<div className="workspace-recent-foot"><Info size={13} /> Each document is checked against the current grant before it opens.</div></section></div><section className="panel workspace-alerts"><div className="panel-heading"><div><div className="eyebrow">REVIEW PROMPTS</div><h2>Needs verification</h2></div><Badge tone="amber">Assistive only</Badge></div><div className="review-alert-grid">{fullSummary && medications.some(m => !m.dose || m.dose.toLowerCase().includes('not recorded')) && <div><AlertCircle size={16} /><span><b>Medication dose missing</b><small>At least one recorded medication has no dose. Verify with the patient/source.</small></span></div>}{fullSummary && allergies.length === 0 && <div><Info size={16} /><span><b>Allergy status not confirmed</b><small>No recorded allergy entry does not mean “no known allergies.”</small></span></div>}{duplicateIds.size > 0 && <div><AlertCircle size={16} /><span><b>Possible duplicate reports</b><small>{duplicateIds.size} shared record(s) may be duplicates. Review before relying on them.</small></span></div>}{records.some(r => !r.date) && <div><Info size={16} /><span><b>Missing report date</b><small>One or more shared records need a date verified.</small></span></div>}{(!(fullSummary && (medications.some(m => !m.dose) || allergies.length === 0)) && duplicateIds.size === 0 && !records.some(r => !r.date)) && <div className="no-review-alert"><CheckCircle2 size={16} /><span><b>No automatic flags in this view</b><small>This is not a clinical assessment; review source documents.</small></span></div>}</div></section></div>}
    {tab === 'timeline' && <div className="workspace-tab-content"><DoctorTimeline records={records} notes={allNotes} patientId={patientId} onOpen={previewRecord} /></div>}
    {tab === 'records' && <div className="workspace-tab-content"><section className="panel doctor-records-panel"><div className="record-toolbar"><div className="record-search"><Search size={15} /><input value={recordSearch} onChange={e => setRecordSearch(e.target.value)} placeholder="Search authorized records…" /></div><Badge tone="blue"><LockKeyhole size={12} /> {records.length} in scope</Badge></div>{accessibleRows.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Shared record</th><th>Category</th><th>Provider</th><th>Date</th><th>Review flags</th><th></th></tr></thead><tbody>{accessibleRows.map(r => <tr key={r.id}><td><button className="table-record-name" onClick={() => previewRecord(r)}><span className={`record-type-icon type-${r.category}`}><FileText size={15} /></span><span><b>{r.title}</b><small>{r.fileName || 'Structured demo data'}</small></span></button></td><td>{CATEGORY_LABELS[r.category]}</td><td>{r.provider}</td><td>{fmtDate(r.date)}</td><td>{duplicateIds.has(r.id) && <Badge tone="amber">Possible duplicate</Badge>}</td><td><button className="icon-button" onClick={() => previewRecord(r)} aria-label="Open authorized record"><ChevronRight size={16} /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={<FileHeart size={23} />} title="No records in this grant" description="Ask the patient to update their sharing scope if you need additional documents." />}</section><div className="fictional-notice"><Info size={13} /> The list is filtered to records explicitly covered by this active consent grant.</div></div>}
    {tab === 'labs' && <div className="workspace-tab-content"><LabComparison tests={tests} selectedTest={selectedTest} setSelectedTest={setCompareTest} rows={labRows} chartReady={chartReady} onOpenRecord={id => { const r = records.find(x => x.id === id); if (r) previewRecord(r) }} /></div>}
    {tab === 'medications' && <div className="workspace-tab-content">{fullSummary ? <MedicationReconciliation medications={medications} doctorId={currentUser.id} reviews={db.medReviews} onReview={markReview} /> : <div className="panel"><EmptyState icon={<LockKeyhole size={23} />} title="Medication list is outside this grant" description="The patient shared selected records only. Ask them to grant access to the health summary if medication reconciliation is needed." /></div>}</div>}
    {tab === 'allergies' && <div className="workspace-tab-content">{fullSummary ? <section className="panel"><div className="panel-heading"><div><div className="eyebrow">PATIENT-SHARED PROFILE</div><h2>Recorded allergies</h2></div><Badge tone="amber">Verify source</Badge></div>{allergies.length ? allergies.map(a => <div className="doctor-allergy-row" key={a.id}><div className="allergy-info-icon"><AlertCircle size={17} /></div><div><b>{a.allergen}</b><small>{a.reaction || 'Reaction not recorded'} · recorded {fmtDate(a.dateRecorded)}</small></div><Badge tone={a.confirmed ? 'blue' : 'amber'}>{a.confirmed ? 'Clinician-confirmed' : 'Patient-reported'}</Badge></div>) : <div className="no-allergy-callout"><Info size={17} /><span><b>Allergy status not confirmed</b><small>No entries in the shared profile. Verify directly with the patient.</small></span></div>}</section> : <div className="panel"><EmptyState icon={<LockKeyhole size={23} />} title="Allergies are not included" description="This grant does not include the patient’s health profile." /></div>}</div>}
    {tab === 'notes' && <div className="workspace-tab-content"><section className="panel clinical-notes-panel"><div className="panel-heading"><div><div className="eyebrow">CLINICIAN AUTHORED</div><h2>Consultation notes</h2></div><Button size="sm" onClick={() => workspaceAction(() => setNoteOpen(true))}><Plus size={14} /> Add note</Button></div><div className="note-authorship-banner"><LockKeyhole size={14} /> Your notes are stored separately from patient-uploaded documents and remain attributed to the author.</div>{ownedNotes.length ? <div className="clinical-note-list">{ownedNotes.map(note => <ClinicalNoteCard note={note} key={note.id} author={fullName(db, note.doctorId)} />)}</div> : <EmptyState icon={<MessageSquareText size={24} />} title="No notes authored by you" description="Add a structured consultation note. The entry will include your name and timestamp." action={<Button size="sm" onClick={() => setNoteOpen(true)}>Add a note</Button>} />}{allNotes.some(n => n.doctorId !== currentUser.id) && <div className="other-notes-notice"><Info size={14} /> Notes authored by other clinicians are not editable in this workspace.</div>}</section><section className="panel diagnosis-entry-panel"><div className="panel-heading"><div><div className="eyebrow">CLINICAL ENTRY</div><h2>Diagnosis entries</h2></div><Button size="sm" variant="outline" onClick={() => workspaceAction(() => setDiagnosisOpen(true))}><Plus size={14} /> Add diagnosis</Button></div>{db.diagnoses.filter(d => d.patientId === patientId && d.doctorId === currentUser.id).length ? db.diagnoses.filter(d => d.patientId === patientId && d.doctorId === currentUser.id).map(d => <div className="diagnosis-row" key={d.id}><Badge tone="blue">Clinician entry</Badge><span><b>{d.condition}</b><small>{fmtDate(d.date)} · {currentUser.name}</small>{d.notes && <small>{d.notes}</small>}</span></div>) : <div className="quiet-empty">No diagnosis entries authored by you. Do not enter an autonomous or unverified diagnosis.</div>}</section><section className="panel diagnosis-entry-panel"><div className="panel-heading"><div><div className="eyebrow">PRESCRIPTION WORKFLOW</div><h2>Prescription drafts</h2></div><Button size="sm" variant="outline" onClick={() => workspaceAction(() => setPrescriptionOpen(true))}><Plus size={14} /> Create draft</Button></div>{db.prescriptionDrafts.filter(d => d.patientId === patientId && d.doctorId === currentUser.id).length ? db.prescriptionDrafts.filter(d => d.patientId === patientId && d.doctorId === currentUser.id).map(d => <div className="draft-prescription" key={d.id}><div><Badge tone="amber">DRAFT · NOT LEGALLY VALID</Badge><h3>{d.medicine}</h3><p>{d.dose || 'Dose not entered'} · {d.frequency || 'Frequency not entered'}</p>{d.instructions && <small>{d.instructions}</small>}</div><span>{currentUser.name}<small>{fmtDateTime(d.createdAt)}</small></span></div>) : <div className="quiet-empty">No prescription drafts created in this workspace.</div>}</section></div>}
    {tab === 'permissions' && <div className="workspace-tab-content"><section className="panel permission-detail-panel"><div className="panel-heading"><div><div className="eyebrow">PATIENT-CONTROLLED PERMISSION</div><h2>Current access</h2></div><Badge tone="green"><i className="status-dot" /> Active</Badge></div><div className="permission-detail-grid"><div><small>GRANTED BY</small><b>{profile.name}</b></div><div><small>ACCESS SCOPE</small><b>{currentScopeText(db, patientId, currentUser.id)}</b></div><div><small>GRANTED</small><b>{fmtDateTime(grant.createdAt)}</b></div><div><small>EXPIRES</small><b>{fmtDateTime(grant.expiresAt)}</b></div></div><div className="permission-note"><ShieldCheck size={16} /><span>The patient controls this grant. You cannot extend, expand, or reapprove access on their behalf. Recheck access before every record retrieval.</span></div></section><section className="panel"><div className="panel-heading"><div><div className="eyebrow">ACCESS HISTORY</div><h2>Related permission activity</h2></div></div>{db.audit.filter(a => a.targetPatientId === patientId && ['grant_created','grant_revoked','request_created','request_responded'].includes(a.action)).slice(0,6).map(a => <div className="permission-audit-row" key={a.id}><span className="audit-icon audit-grant"><ShieldCheck size={15} /></span><span><b>{a.detail}</b><small>{fmtDateTime(a.timestamp)}</small></span></div>)}<div className="fictional-notice"><Info size={13} /> Patient can revoke this grant at any time from their portal.</div></section></div>}
    <div className="workspace-footer-disclaimer"><Info size={13} /> Clinical entries are demo-only and require professional verification. No autonomous diagnoses or medication instructions are generated.</div>
    <RecordPreview open={!!recordPreview} record={recordPreview} onClose={() => setRecordPreview(null)} onDownload={recordDownload} />
    <NoteForm open={noteOpen} busy={saving} onClose={() => setNoteOpen(false)} onSubmit={saveNote} />
    <DiagnosisForm open={diagnosisOpen} onClose={() => setDiagnosisOpen(false)} onSubmit={saveDiagnosis} />
    <PrescriptionForm open={prescriptionOpen} onClose={() => setPrescriptionOpen(false)} onSubmit={saveDraft} />
    <DoctorSummaryModal open={summaryOpen} onClose={() => setSummaryOpen(false)} profileName={profile.name} patientId={patient?.patientId || '—'} records={records} conditions={conditions} meds={medications} allergies={allergies} surgeries={surgeries} fullSummary={fullSummary} onExport={exportSummary} />
  </div>
}

function DoctorTimeline({ records, notes, patientId, onOpen }: { records: MedicalRecord[]; notes: ConsultationNote[]; patientId: string; onOpen: (r: MedicalRecord) => void }) {
  const events = [...records.map(r => ({ id: r.id, date: r.date, title: r.title, detail: r.labResults?.map(l => `${l.test}: ${l.value} ${l.unit}`).join(' · ') || r.notes || CATEGORY_LABELS[r.category], provider: r.provider, record: r })), ...notes.map(n => ({ id: n.id, date: n.visitDate, title: 'Consultation note', detail: n.chiefComplaint, provider: 'Clinician note', record: undefined }))].sort((a,b)=>b.date.localeCompare(a.date))
  return <section className="panel doctor-timeline-panel"><div className="panel-heading"><div><div className="eyebrow">AUTHORIZED HISTORY</div><h2>Medical timeline</h2></div><Badge tone="blue">{events.length} in scope</Badge></div>{events.length ? <div className="doctor-timeline">{events.map(e => <div className="doctor-timeline-row" key={e.id}><span className="timeline-date">{fmtDate(e.date)}</span><span className="doctor-timeline-dot" /><div className="doctor-timeline-event"><span className="eyebrow">{e.record ? CATEGORY_LABELS[e.record.category] : 'CLINICAL NOTE'}</span><h3>{e.record ? <button onClick={() => onOpen(e.record!)}>{e.title} <ArrowUpRight size={13} /></button> : e.title}</h3><p>{e.detail}</p><small>{e.provider}</small></div></div>)}</div> : <EmptyState icon={<Activity size={23} />} title="No authorized timeline events" description="Shared records and notes will appear chronologically here." />}</section>
}

function LabComparison({ tests, selectedTest, setSelectedTest, rows, chartReady, onOpenRecord }: { tests: string[]; selectedTest: string; setSelectedTest: (v: string) => void; rows: { test: string; value: string; numericValue?: number; unit: string; referenceRange?: string; date: string; title: string; provider: string; recordId: string }[]; chartReady: boolean; onOpenRecord: (id: string) => void }) {
  return <div className="lab-comparison-layout"><section className="panel lab-chart-panel"><div className="panel-heading"><div><div className="eyebrow">TEST RESULT COMPARISON</div><h2>Compare available results</h2></div><Badge tone="blue">Source-linked</Badge></div>{tests.length ? <><div className="lab-select-row"><label><span>Test name</span><select value={selectedTest} onChange={e => setSelectedTest(e.target.value)}>{tests.map(t => <option key={t}>{t}</option>)}</select></label><span className="lab-data-count">{rows.length} result{rows.length === 1 ? '' : 's'}</span></div>{chartReady ? <><div className="lab-chart-heading"><b>{selectedTest}</b><span>{rows[0].unit} · values as supplied</span></div><div className="chart-wrap doctor-lab-chart"><ResponsiveContainer width="100%" height={230}><AreaChart data={rows.map(r => ({ ...r, label: new Date(r.date).toLocaleDateString('en-IN', { month: 'short', year: '2-digit' }) }))} margin={{ top: 14, right: 16, bottom: 0, left: -12 }}><defs><linearGradient id="labFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#298caa" stopOpacity={0.2} /><stop offset="95%" stopColor="#298caa" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid stroke="#edf2f6" vertical={false} /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: '#7f90a0', fontSize: 11 }} dy={9} /><YAxis axisLine={false} tickLine={false} tick={{ fill: '#7f90a0', fontSize: 11 }} /><Tooltip formatter={(value: number) => [`${value} ${rows[0].unit}`, selectedTest]} labelFormatter={(_, payload) => payload?.[0]?.payload?.date ? fmtDate(payload[0].payload.date) : ''} contentStyle={{ borderRadius: 10, borderColor: '#dce7ed', fontSize: 12 }} /><Area type="monotone" dataKey="numericValue" stroke="#168a97" strokeWidth={2.5} fill="url(#labFill)" activeDot={{ r: 5, fill: '#168a97', stroke: 'white', strokeWidth: 2 }} /></AreaChart></ResponsiveContainer></div><div className="chart-caution"><Info size={13} /> Trend visualization only. Values may lack clinical context; verify units, methods, and reference ranges.</div></> : rows.length > 0 ? <div className="lab-no-chart"><Info size={17} /><div><b>A trend chart is not available for these results</b><p>{Array.from(new Set(rows.map(r => r.unit))).length > 1 ? 'Units differ across reports; values are not plotted together.' : 'Numeric values or multiple comparable results are not available.'} The entries remain visible below with original units.</p></div></div> : <div className="quiet-empty">No results for this test in the active share.</div>}</> : <EmptyState icon={<Activity size={24} />} title="No lab results in this share" description="When authorized reports include structured lab values, they can be compared here." />}</section><section className="panel lab-results-table-panel"><div className="panel-heading"><div><div className="eyebrow">ORIGINAL SOURCE VALUES</div><h2>Result details</h2></div></div>{rows.length ? <div className="table-scroll"><table className="data-table lab-results-table"><thead><tr><th>Date</th><th>Value</th><th>Reference range</th><th>Source</th></tr></thead><tbody>{rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map((row, i) => <tr key={`${row.recordId}-${i}`}><td>{fmtDate(row.date)}</td><td><b>{row.value} {row.unit}</b></td><td>{row.referenceRange || <span className="muted-copy">Not supplied</span>}</td><td><button className="text-action" onClick={() => onOpenRecord(row.recordId)}>{row.title} <ArrowUpRight size={12} /></button></td></tr>)}</tbody></table></div> : <div className="quiet-empty">No available test records.</div>}<div className="lab-reference-note"><AlertCircle size={14} /> Reference ranges are shown exactly as supplied. They are not interpreted or normalized by MediVault.</div></section></div>
}

function MedicationReconciliation({ medications, doctorId, reviews, onReview }: { medications: Medication[]; doctorId: string; reviews: ReturnType<typeof useStore>['db']['medReviews']; onReview: (m: Medication, outcome: 'reviewed' | 'continued' | 'changed' | 'discontinued') => void }) {
  const active = medications.filter(m => m.status === 'active')
  const normalizeMeds = active.map(m => ({ ...m, duplicate: active.some(other => other.id !== m.id && normalize(other.name) === normalize(m.name)) }))
  const missingDose = active.filter(m => !m.dose || m.dose.toLowerCase().includes('not recorded'))
  return <div className="page-stack inside-workspace"><section className="panel reconciliation-panel"><div className="panel-heading"><div><div className="eyebrow">MEDICATION RECONCILIATION</div><h2>Recorded medications</h2></div><Badge tone="amber">Review prompts only</Badge></div><div className="reconciliation-disclaimer"><Info size={14} /> These flags are data-quality prompts, not interaction checks or clinical conclusions. Verify against original sources and the patient.</div>{medications.length ? <div className="table-scroll"><table className="data-table reconcile-table"><thead><tr><th>Medication</th><th>Recorded dose / frequency</th><th>Status</th><th>Review flags</th><th>My review</th></tr></thead><tbody>{normalizeMeds.concat(medications.filter(m => m.status !== 'active').map(m => ({ ...m, duplicate: false }))).map(m => { const review = reviews.find(r => r.medicationId === m.id && r.doctorId === doctorId); const overlaps = medications.some(other => other.id !== m.id && normalize(other.name) === normalize(m.name) && other.startDate <= (m.endDate || dateOnly(new Date())) && m.startDate <= (other.endDate || dateOnly(new Date()))); return <tr key={m.id}><td><b>{m.name}</b><small>From patient-shared health summary</small></td><td>{m.dose || 'Dose not recorded'}<small>{m.frequency || 'Frequency not recorded'}</small></td><td><Badge tone={m.status === 'active' ? 'green' : 'neutral'}>{m.status}</Badge></td><td><div className="med-flag-list">{(!m.dose || m.dose.toLowerCase().includes('not recorded')) && <Badge tone="amber">Dose missing</Badge>}{m.duplicate && <Badge tone="amber">Possible duplicate</Badge>}{overlaps && <Badge tone="amber">Possible date overlap</Badge>}{overlaps && medications.some(other => other.id !== m.id && normalize(other.name) === normalize(m.name) && other.status !== m.status) && <Badge tone="amber">Conflicting status</Badge>}{!m.duplicate && !overlaps && m.dose && m.dose.toLowerCase() !== 'not recorded' && <span className="muted-copy">No prompt</span>}</div></td><td>{review ? <span className="review-outcome"><CheckCircle2 size={14} /> {review.outcome}<small>{fmtDateTime(review.reviewedAt)}</small></span> : <select className="review-select" defaultValue="" onChange={e => { if (e.target.value) onReview(m, e.target.value as 'reviewed' | 'continued' | 'changed' | 'discontinued') }}><option value="" disabled>Mark reviewed…</option><option value="reviewed">Reviewed</option><option value="continued">Continue</option><option value="changed">Changed</option><option value="discontinued">Discontinue</option></select>}</td></tr>})}</tbody></table></div> : <EmptyState icon={<HeartPulse size={24} />} title="No shared medication list" description="The patient has not included structured medications in this grant." />}</section><section className="panel reconcile-notice"><div className="review-alert-grid"><div><Info size={16} /><span><b>Historical entries are retained</b><small>Discontinued medications remain visible for reconciliation context.</small></span></div><div><AlertCircle size={16} /><span><b>Potential overlap requires clinician review</b><small>MediVault does not determine whether two prescriptions are appropriate together.</small></span></div></div></section></div>
}

function ClinicalNoteCard({ note, author }: { note: ConsultationNote; author: string }) {
  return <article className="clinical-note-card"><div className="clinical-note-head"><span className="note-date-chip"><CalendarDays size={13} /> {fmtDate(note.visitDate)}</span><Badge tone="blue"><UserRound size={11} /> {author}</Badge><small>Saved {fmtDateTime(note.createdAt)}</small></div><div className="clinical-note-fields"><div><small>CHIEF COMPLAINT</small><p>{note.chiefComplaint}</p></div><div><small>OBSERVATIONS</small><p>{note.observations || 'Not entered'}</p></div><div><small>ASSESSMENT</small><p>{note.assessment || 'Not entered'}</p></div><div><small>PLAN</small><p>{note.plan || 'Not entered'}</p></div>{note.followUpDate && <div className="follow-up-row"><CalendarDays size={13} /> Follow-up recorded for {fmtDate(note.followUpDate)}</div>}</div></article>
}

function NoteForm({ open, busy, onClose, onSubmit }: { open: boolean; busy: boolean; onClose: () => void; onSubmit: (data: Omit<ConsultationNote, 'id' | 'patientId' | 'doctorId' | 'createdAt'>) => void }) {
  const [form, setForm] = useState({ visitDate: dateOnly(new Date()), chiefComplaint: '', observations: '', assessment: '', plan: '', followUpDate: '' })
  const [error, setError] = useState('')
  useEffect(() => { if (open) { setForm({ visitDate: dateOnly(new Date()), chiefComplaint: '', observations: '', assessment: '', plan: '', followUpDate: '' }); setError('') } }, [open])
  if (!open) return null
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!form.chiefComplaint.trim()) return setError('Enter a chief complaint before saving.'); setError(''); onSubmit({ ...form, chiefComplaint: form.chiefComplaint.trim() }) }
  return <Modal open={open} title="Consultation note" eyebrow="CLINICIAN-AUTHORED · PRIVATE TO YOUR WORKSPACE" onClose={onClose} wide><form className="modal-form" onSubmit={submit}><div className="form-grid"><Field label="Visit date" required><input type="date" value={form.visitDate} onChange={e => setForm({ ...form, visitDate: e.target.value })} /></Field><Field label="Follow-up date"><input type="date" value={form.followUpDate} onChange={e => setForm({ ...form, followUpDate: e.target.value })} /></Field></div><Field label="Chief complaint" required><textarea rows={2} value={form.chiefComplaint} onChange={e => setForm({ ...form, chiefComplaint: e.target.value })} placeholder="Record the patient’s stated reason for consultation." /></Field><Field label="Observations"><textarea rows={3} value={form.observations} onChange={e => setForm({ ...form, observations: e.target.value })} placeholder="Document observations from the visit…" /></Field><Field label="Assessment"><textarea rows={3} value={form.assessment} onChange={e => setForm({ ...form, assessment: e.target.value })} placeholder="Clinician-authored assessment; no automated diagnosis." /></Field><Field label="Plan"><textarea rows={3} value={form.plan} onChange={e => setForm({ ...form, plan: e.target.value })} placeholder="Document a plan as discussed with the patient." /></Field>{error && <div className="form-error">{error}</div>}<div className="note-form-warning"><Info size={14} /> Demo note only. This does not replace a certified clinical record system.</div><div className="modal-foot"><span className="local-storage-note"><UserRound size={13} /> Authored by your signed-in account</span><div><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Save note</Button></div></div></form></Modal>
}

function DiagnosisForm({ open, onClose, onSubmit }: { open: boolean; onClose: () => void; onSubmit: (condition: string, date: string, notes: string) => void }) {
  const [condition, setCondition] = useState(''); const [date, setDate] = useState(dateOnly(new Date())); const [notes, setNotes] = useState(''); const [error, setError] = useState('')
  useEffect(() => { if (open) { setCondition(''); setDate(dateOnly(new Date())); setNotes(''); setError('') } }, [open])
  if (!open) return null
  return <Modal open={open} title="Add diagnosis entry" eyebrow="CLINICIAN-AUTHORED ENTRY" onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); if (!condition.trim()) return setError('Enter the diagnosis or condition from your clinical assessment.'); onSubmit(condition.trim(), date, notes.trim()) }}><Field label="Diagnosis / condition" required><input value={condition} onChange={e => setCondition(e.target.value)} placeholder="Enter clinician-authored entry" autoFocus /></Field><Field label="Date" required><input type="date" value={date} onChange={e => setDate(e.target.value)} /></Field><Field label="Context / source"><textarea rows={3} value={notes} onChange={e => setNotes(e.target.value)} placeholder="Optional note, including source context…" /></Field>{error && <div className="form-error">{error}</div>}<div className="note-form-warning"><Info size={14} /> This entry is attributed to you; MediVault does not generate diagnoses.</div><div className="modal-foot"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit">Save diagnosis entry</Button></div></form></Modal>
}

function PrescriptionForm({ open, onClose, onSubmit }: { open: boolean; onClose: () => void; onSubmit: (draft: { medicine: string; dose: string; frequency: string; instructions: string }) => void }) {
  const [form, setForm] = useState({ medicine: '', dose: '', frequency: '', instructions: '' }); const [error, setError] = useState('')
  useEffect(() => { if (open) { setForm({ medicine: '', dose: '', frequency: '', instructions: '' }); setError('') } }, [open])
  if (!open) return null
  return <Modal open={open} title="Prescription draft" eyebrow="NOT LEGALLY VALID · NOT A PRESCRIPTION" onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); if (!form.medicine.trim()) return setError('Enter a medicine name or item for the draft.'); onSubmit({ ...form, medicine: form.medicine.trim() }) }}><div className="draft-warning"><ShieldAlert size={16} /><span><b>Draft only — not legally valid.</b><small>Does not provide or recommend medication instructions. Verify all clinical decisions with the patient and applicable standards.</small></span></div><Field label="Medicine / item name" required><input value={form.medicine} onChange={e => setForm({ ...form, medicine: e.target.value })} placeholder="Clinician-entered draft item" autoFocus /></Field><Field label="Dose (if documented)"><input value={form.dose} onChange={e => setForm({ ...form, dose: e.target.value })} placeholder="Do not infer missing details" /></Field><Field label="Frequency (if documented)"><input value={form.frequency} onChange={e => setForm({ ...form, frequency: e.target.value })} placeholder="Do not infer missing details" /></Field><Field label="Draft notes"><textarea rows={3} value={form.instructions} onChange={e => setForm({ ...form, instructions: e.target.value })} placeholder="Optional clinician-entered note." /></Field>{error && <div className="form-error">{error}</div>}<div className="modal-foot"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit">Save draft</Button></div></form></Modal>
}

function DoctorSummaryModal({ open, onClose, profileName, patientId, records, conditions, meds, allergies, surgeries, fullSummary, onExport }: { open: boolean; onClose: () => void; profileName: string; patientId: string; records: MedicalRecord[]; conditions: ReturnType<typeof useStore>['db']['conditions']; meds: Medication[]; allergies: ReturnType<typeof useStore>['db']['allergies']; surgeries: Surgery[]; fullSummary: boolean; onExport: () => void }) {
  const tests = records.flatMap(r => (r.labResults || []).map(l => ({ ...l, title: r.title, date: r.date }))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8)
  const missing = [!fullSummary ? 'Health summary was outside the granted scope.' : '', fullSummary && allergies.length === 0 ? 'Allergy status is unknown; no entry was shared.' : '', meds.some(m => !m.dose) ? 'At least one medication dose was not recorded.' : '', records.some(r => !r.date) ? 'Some source record dates are missing.' : ''].filter(Boolean)
  return <Modal open={open} title="Generated medical summary" eyebrow="DETERMINISTIC DEMO SUMMARY · CLINICIAN VERIFICATION REQUIRED" onClose={onClose} wide><div className="ai-summary-warning"><Activity size={17} /><div><b>AI-style summary · assistive, not clinical advice</b><p>This deterministic summary uses only currently authorized structured demo data. Verify every fact against the cited source and with the patient before any clinical use.</p></div></div><div className="summary-patient-label"><b>{profileName}</b><span>Patient ID · {patientId}</span><span>Generated {fmtDateTime(new Date().toISOString())}</span></div><div className="generated-summary-sections"><SummarySection title="Recorded conditions" items={fullSummary ? conditions.map(c => ({ text: c.condition, source: `${c.confirmed ? 'Clinician-confirmed' : 'Patient-reported'} · ${c.recordedBy} · ${fmtDate(c.diagnosedDate)}` })) : []} empty={fullSummary ? 'No condition entries in shared profile.' : 'Not available in this grant.'} /><SummarySection title="Current & historical medications" items={fullSummary ? meds.map(m => ({ text: `${m.name} · ${m.dose || 'dose not recorded'} · ${m.status}`, source: `Patient medication list · ${fmtDate(m.startDate)}` })) : []} empty={fullSummary ? 'No medication entries available.' : 'Not available in this grant.'} /><SummarySection title="Recorded allergies" items={fullSummary ? allergies.map(a => ({ text: `${a.allergen} — ${a.reaction || 'reaction not recorded'}`, source: `${a.confirmed ? 'Clinician-confirmed' : 'Patient-reported'} · ${fmtDate(a.dateRecorded)}` })) : []} empty={fullSummary ? 'No allergy entries; status remains unknown.' : 'Not available in this grant.'} /><SummarySection title="Recent test results" items={tests.map(t => ({ text: `${t.test}: ${t.value} ${t.unit}`, source: `${t.title} · ${fmtDate(t.date)}${t.referenceRange ? ` · reference supplied: ${t.referenceRange}` : ' · reference range not supplied'}` }))} empty="No structured test results in authorized records." /><SummarySection title="Important past procedures" items={fullSummary ? surgeries.map(s => ({ text: s.procedure, source: `${fmtDate(s.date)} · ${s.hospital || 'provider not recorded'}` })) : []} empty={fullSummary ? 'No procedure entries were found in the shared structured demo data.' : 'Not available in this grant.'} /><section className="summary-alerts"><h3>Missing or conflicting information</h3>{missing.length || meds.length ? <ul>{missing.map((m, i) => <li key={i}>{m}</li>)}{meds.filter(m => !m.dose).map(m => <li key={m.id}>Dose missing for {m.name} — needs verification.</li>)}</ul> : <p>No structured gaps flagged. This is not proof that the source record is complete.</p>}</section></div><div className="summary-source-footer"><Info size={14} /> Sources are listed with document titles and dates when available. No missing details are inferred.</div><div className="modal-foot"><span className="local-storage-note"><LockKeyhole size={13} /> Only records currently in the active grant</span><div><Button variant="outline" onClick={onClose}>Close</Button><Button onClick={onExport}><ArrowDownToLine size={14} /> Print / export</Button></div></div></Modal>
}
function SummarySection({ title, items, empty }: { title: string; items: { text: string; source: string }[]; empty: string }) { return <section className="summary-section"><h3>{title}</h3>{items.length ? items.map((item, i) => <div className="summary-fact" key={i}><b>{item.text}</b><small>{item.source}</small></div>) : <div className="summary-empty">{empty}</div>}</section> }

export function DoctorRequestsPage() {
  const { db, currentUser, createAccessRequest, mutate, addAudit } = useStore()
  const toast = useToast()
  const [patientId, setPatientId] = useState('')
  const [requestMessage, setRequestMessage] = useState('Requesting access to selected records for a consultation.')
  const [emergencyToken, setEmergencyToken] = useState('')
  const [emergencyReason, setEmergencyReason] = useState('')
  const [error, setError] = useState('')
  const [emergencyError, setEmergencyError] = useState('')
  const [emergencyCase, setEmergencyCase] = useState<EmergencyAccess | null>(null)
  useEffect(() => {
    const match = window.location.hash.match(/^#emergency\/(.+)$/)
    if (match) setEmergencyToken(decodeURIComponent(match[1]))
  }, [])
  if (!currentUser) return null
  const myRequests = db.accessRequests.filter(r => r.doctorId === currentUser.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))
  const submitRequest = (event: React.FormEvent) => { event.preventDefault(); setError(''); if (!patientId.trim()) return setError('Enter the patient’s unique ID.'); const result = createAccessRequest(patientId, requestMessage); if (!result.ok) return setError(result.message); toast(result.message, 'info'); setPatientId('') }
  const submitEmergency = (event: React.FormEvent) => {
    event.preventDefault(); setEmergencyError('')
    if (!emergencyToken.trim() || !emergencyReason.trim()) return setEmergencyError('A protected workflow token and a reason are required.')
    const token = db.emergencyTokens.find(t => t.active && t.token === emergencyToken.trim())
    if (!token) return setEmergencyError('Token not recognized. No patient information was disclosed.')
    if (db.emergency.some(e => e.token === emergencyToken.trim() && e.doctorId === currentUser.id && e.status === 'pending')) return setEmergencyError('A pending request already exists for this token.')
    const access: EmergencyAccess = { id: uid('emergency'), token: emergencyToken.trim(), patientId: token.patientId, doctorId: currentUser.id, reason: emergencyReason.trim(), createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 30 * 60000).toISOString(), status: 'pending' }
    mutate(prev => ({ ...prev, emergency: [access, ...prev.emergency] }))
    addAudit('emergency_access', 'Requested narrow emergency workflow access. Explicit patient authorization is required; no bypass is configured.', token.patientId)
    toast('Emergency request sent. No information is available until authorized.', 'info'); setEmergencyReason(''); setEmergencyCase(null)
  }
  const activeEmergency = db.emergency.filter(e => e.doctorId === currentUser.id && e.status === 'active' && !isExpired(e.expiresAt))
  const statusLabel = (r: AccessRequest) => r.status === 'pending' ? 'Pending' : r.status === 'approved' ? 'Approved' : 'Rejected'
  return <div className="page-stack"><PageTitle eyebrow="LEAST-PRIVILEGE ACCESS" title="Access requests" description="Request consent by patient ID. The identifier alone never reveals records." action={<Badge tone="blue"><LockKeyhole size={13} /> No access by default</Badge>} /><div className="request-page-grid"><section className="panel access-request-form-panel"><div className="panel-heading"><div><div className="eyebrow">PATIENT CONSENT REQUEST</div><h2>Request record access</h2></div><span className="request-form-icon"><HeartHandshake size={18} /></span></div><p className="section-intro">Enter a patient’s unique MediVault ID. We send a request for their review without disclosing whether a record exists.</p><form className="modal-form" onSubmit={submitRequest}><Field label="Patient ID" required hint="A matching patient will receive a request. No records appear until they choose a scope and expiry."><input value={patientId} onChange={e => setPatientId(e.target.value)} placeholder="e.g. MV-2026-0142" /></Field><Field label="Reason for access"><textarea rows={3} value={requestMessage} onChange={e => setRequestMessage(e.target.value)} /></Field>{error && <div className="form-error"><AlertCircle size={14} /> {error}</div>}<Button type="submit"><HeartHandshake size={15} /> Send request</Button></form><div className="request-security-note"><ShieldCheck size={15} /> The patient must explicitly approve a specific scope and expiry. You cannot approve your own request.</div></section>
    <section className="panel emergency-request-panel"><div className="panel-heading"><div><div className="eyebrow">DEMO EMERGENCY WORKFLOW</div><h2>Request essential access</h2></div><Badge tone="amber"><Clock3 size={12} /> 30 min max</Badge></div><div className="emergency-request-callout"><ShieldAlert size={17} /><span><b>Not a consent bypass.</b><small>Requires a reason and explicit patient authorization before essential-only access; if consent is unavailable, access stays denied.</small></span></div><form className="modal-form" onSubmit={submitEmergency}><Field label="Protected QR workflow token" required hint="Scan the patient’s QR workflow or paste its token. No health details are encoded."><input value={emergencyToken} onChange={e => setEmergencyToken(e.target.value)} placeholder="Protected workflow token" /></Field><Field label="Reason for emergency request" required><textarea rows={3} value={emergencyReason} onChange={e => setEmergencyReason(e.target.value)} placeholder="Document the reason for this narrowly-scoped request." /></Field>{emergencyError && <div className="form-error"><AlertCircle size={14} /> {emergencyError}</div>}<Button variant="outline" type="submit"><ShieldAlert size={15} /> Send emergency request</Button></form>{activeEmergency.length > 0 && <div className="active-emergency-list"><h3>Authorized emergency access</h3>{activeEmergency.map(item => <div className="active-emergency-row" key={item.id}><span><b>Essential information only</b><small>Expires {fmtDateTime(item.expiresAt)}</small></span><Button size="sm" onClick={() => setEmergencyCase(item)}>Open essential card</Button></div>)}</div>}</section></div>
    <section className="panel outgoing-requests-panel"><div className="panel-heading"><div><div className="eyebrow">REQUEST HISTORY</div><h2>Your patient requests</h2></div><Badge tone="neutral">{myRequests.length}</Badge></div>{myRequests.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Patient</th><th>Requested</th><th>Status</th><th>Next step</th></tr></thead><tbody>{myRequests.map(r => <tr key={r.id}><td><b>{activeGrantFor(db, r.patientId, currentUser.id) ? fullName(db, r.patientId) : 'Patient (identity protected)'}</b><small>{activeGrantFor(db, r.patientId, currentUser.id) ? db.patients.find(p => p.profileId === r.patientId)?.patientId : 'No records disclosed'}</small></td><td>{fmtDateTime(r.createdAt)}</td><td><Badge tone={r.status === 'approved' ? 'green' : r.status === 'pending' ? 'amber' : 'neutral'}>{statusLabel(r)}</Badge></td><td>{r.status === 'pending' ? 'Wait for patient' : r.status === 'approved' ? 'Open authorized workspace' : 'Patient declined'}</td></tr>)}</tbody></table></div> : <EmptyState icon={<HeartHandshake size={23} />} title="No access requests yet" description="Your requests and patient responses will appear here." />}</section>
    <section className="panel request-policy"><ShieldCheck size={17} /><div><b>Access control is checked every time a protected record is opened.</b><p>Pending, rejected, expired, or revoked permissions do not expose records in the workspace.</p></div></section>
    <Modal open={!!emergencyCase} title="Essential emergency information" eyebrow="AUTHORIZED EMERGENCY DEMO · TEMPORARY" onClose={() => setEmergencyCase(null)}>{emergencyCase && <EmergencyEssentialCard access={emergencyCase} />}</Modal><div className="fictional-notice"><Info size={14} /> Emergency requests in this hackathon demo are local simulations. Always contact real emergency services in a real emergency.</div></div>
}

function EmergencyEssentialCard({ access }: { access: EmergencyAccess }) {
  const { db, currentUser, mutate, addAudit } = useStore()
  const toast = useToast()
  const allowed = access.status === 'active' && !isExpired(access.expiresAt) && currentUser?.id === access.doctorId
  const patient = db.patients.find(p => p.profileId === access.patientId)
  const profile = db.profiles.find(p => p.id === access.patientId)
  const allergies = db.allergies.filter(a => a.patientId === access.patientId).sort((a,b) => (a.severity === 'severe' ? 0 : 1) - (b.severity === 'severe' ? 0 : 1))
  const meds = db.medications.filter(m => m.patientId === access.patientId && m.status === 'active')
  const conditions = db.conditions.filter(c => c.patientId === access.patientId)
  if (!allowed) return <div className="access-denied-inline"><ShieldAlert size={20} /><b>Access denied</b><span>This emergency request has expired, is not authorized, or has been revoked.</span></div>
  return <div className="emergency-essential-summary"><div className="emergency-access-status"><Badge tone="amber"><Clock3 size={12} /> Temporary · expires {fmtDateTime(access.expiresAt)}</Badge><span>Approved explicitly by the patient</span></div><div className="emergency-reason"><small>REQUEST REASON</small><p>{access.reason}</p></div><div className="emergency-essential-list"><div><small>PATIENT IDENTIFIER</small><b>{patient?.patientId}</b></div><div><small>RECORDED ALLERGIES</small><b>{allergies.length ? allergies.map(a => `${a.allergen} · ${a.reaction || 'reaction not recorded'} · ${a.confirmed ? 'confirmed' : 'patient-reported'}`).join('; ') : 'No entries · verify status'}</b></div><div><small>CURRENT MEDICATIONS</small><b>{meds.length ? meds.map(m => `${m.name} · ${m.dose || 'dose not recorded'}`).join('; ') : 'None recorded'}</b></div><div><small>RECORDED CONDITIONS</small><b>{conditions.length ? conditions.map(c => c.condition).join('; ') : 'None recorded'}</b></div><div><small>EMERGENCY CONTACT</small><b>{patient?.emergencyContactName || 'Not recorded'} · {patient?.emergencyContactPhone || 'No phone recorded'}</b></div></div><p className="emergency-limits"><LockKeyhole size={13} /> This temporary workflow exposes essential card fields only — not medical documents or the full history.</p><Button variant="outline" size="sm" onClick={() => { mutate(prev => ({ ...prev, emergency: prev.emergency.map(e => e.id === access.id ? { ...e, status: 'expired' as const } : e) })); addAudit('emergency_access', 'Closed temporary emergency access.', access.patientId); toast('Emergency access closed.'); }}>Close emergency access</Button></div>
}

export function DoctorAppointmentsPage() {
  const { db, currentUser, mutate } = useStore()
  const toast = useToast()
  const [createOpen, setCreateOpen] = useState(false)
  const [form, setForm] = useState({ patientId: '', dateTime: '', clinic: '', notes: '' })
  const [error, setError] = useState('')
  if (!currentUser) return null
  const myAppts = db.appointments.filter(a => a.doctorId === currentUser.id).sort((a,b)=>a.dateTime.localeCompare(b.dateTime))
  const authorized = activePatientIds(db, currentUser.id)
  const create = (event: React.FormEvent) => {
    event.preventDefault(); setError('')
    if (!form.patientId || !form.dateTime || !form.clinic.trim()) return setError('Choose an authorized patient, proposed time and clinic.')
    if (!activeGrantFor(db, form.patientId, currentUser.id)) return setError('Patient access is no longer active. Cannot create this proposal.')
    const appointment: Appointment = { id: uid('appointment'), patientId: form.patientId, doctorId: currentUser.id, dateTime: new Date(form.dateTime).toISOString(), clinic: form.clinic.trim(), status: 'proposed', notes: form.notes.trim(), createdBy: 'doctor' }
    mutate(prev => ({ ...prev, appointments: [appointment, ...prev.appointments] }))
    toast('Appointment proposal sent to the patient in the demo.'); setCreateOpen(false); setForm({ patientId: '', dateTime: '', clinic: '', notes: '' })
  }
  const sections: [string, Appointment[]][] = [['Awaiting patient response', myAppts.filter(a => a.status === 'proposed')], ['Accepted appointments', myAppts.filter(a => a.status === 'accepted' && new Date(a.dateTime) >= new Date())], ['Past & inactive', myAppts.filter(a => !['proposed','accepted'].includes(a.status) || new Date(a.dateTime) < new Date())]]
  return <div className="page-stack"><PageTitle eyebrow="SIMULATED SCHEDULING" title="Appointments" description="View proposed times with patients who have an active share and create follow-up proposals." action={<Button onClick={() => setCreateOpen(true)} disabled={!authorized.length}><Plus size={15} /> Propose appointment</Button>} />{sections.map(([label, rows]) => <section className="appointment-section" key={label}><div className="section-line-heading"><div><h2>{label}</h2><span>{rows.length} item{rows.length === 1 ? '' : 's'}</span></div></div>{rows.length ? <div className="appointment-list">{rows.map(a => <DoctorAppointmentCard key={a.id} appointment={a} />)}</div> : <div className="quiet-empty">No appointments in this section.</div>}</section>)}{!authorized.length && <div className="fictional-notice"><LockKeyhole size={14} /> Appointment proposals can be sent only to patients currently authorized to your account.</div>}<Modal open={createOpen} title="Propose an appointment" eyebrow="SIMULATED CLINIC SCHEDULING" onClose={() => setCreateOpen(false)}><form className="modal-form" onSubmit={create}><Field label="Authorized patient" required><select value={form.patientId} onChange={e => setForm({ ...form, patientId: e.target.value })}><option value="">Select a patient</option>{authorized.map(id => <option key={id} value={id}>{fullName(db,id)} · {db.patients.find(p=>p.profileId===id)?.patientId}</option>)}</select></Field><Field label="Proposed date and time" required><input type="datetime-local" value={form.dateTime} min={new Date().toISOString().slice(0,16)} onChange={e => setForm({ ...form, dateTime: e.target.value })} /></Field><Field label="Clinic / location" required><input value={form.clinic} onChange={e => setForm({ ...form, clinic: e.target.value })} placeholder="Clinic or video visit" /></Field><Field label="Note to patient"><textarea rows={3} value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Optional note…" /></Field>{error && <div className="form-error">{error}</div>}<div className="note-form-warning"><Info size={14} /> Simulated proposal only. The patient must accept; no real booking is made.</div><div className="modal-foot"><Button variant="outline" onClick={() => setCreateOpen(false)}>Cancel</Button><Button type="submit">Send proposal</Button></div></form></Modal></div>
}

function DoctorAppointmentCard({ appointment }: { appointment: Appointment }) {
  const { db, currentUser, mutate } = useStore()
  const toast = useToast()
  const patient = db.patients.find(p => p.profileId === appointment.patientId)
  const authorized = !!currentUser && !!activeGrantFor(db, appointment.patientId, currentUser.id)
  return <article className="appointment-card"><div className="appt-date-block"><small>{new Date(appointment.dateTime).toLocaleDateString('en-IN', { month: 'short' }).toUpperCase()}</small><b>{new Date(appointment.dateTime).getDate()}</b><span>{new Date(appointment.dateTime).toLocaleDateString('en-IN', { weekday: 'short' })}</span></div><div className="appointment-main"><div className="appointment-heading"><h3>{authorized ? fullName(db, appointment.patientId) : 'Patient appointment'}</h3><Badge tone={appointment.status === 'accepted' ? 'green' : appointment.status === 'proposed' ? 'amber' : 'neutral'}>{appointment.status}</Badge></div><p>{authorized ? `${patient?.patientId || 'ID not recorded'} · ` : 'Identity restricted · '}{appointment.clinic}</p><div className="appointment-meta"><span><Clock3 size={14} /> {new Date(appointment.dateTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}</span><span><CalendarDays size={14} /> {fmtDate(appointment.dateTime)}</span></div>{appointment.notes && <div className="appointment-note"><MessageSquareText size={13} /> {appointment.notes}</div>}</div>{appointment.status === 'proposed' && <div className="appointment-actions"><Button size="sm" variant="outline" onClick={() => { mutate(prev => ({ ...prev, appointments: prev.appointments.map(a => a.id === appointment.id ? { ...a, status: 'cancelled' as const } : a) })); toast('Appointment proposal cancelled.') }}>Cancel proposal</Button></div>}</article>
}

export function DoctorActivityPage() {
  const { db, currentUser } = useStore()
  if (!currentUser) return null
  const logs = db.audit.filter(a => a.actorId === currentUser.id)
  const actionLabels: Record<string, string> = { login: 'Signed in', logout: 'Signed out', record_view: 'Authorized record viewed', record_download: 'Authorized record downloaded', grant_created: 'Consent grant created', grant_revoked: 'Access revoked', request_created: 'Access requested', request_responded: 'Patient request responded', note_created: 'Clinical entry created', appointment_responded: 'Appointment updated', emergency_access: 'Emergency workflow activity', summary_generated: 'Summary generated', record_upload: 'Record uploaded', record_delete: 'Record deleted' }
  return <div className="page-stack"><PageTitle eyebrow="CLINICIAN ACTIVITY" title="Activity log" description="A local demo view of actions performed by this clinician account." action={<Badge tone="blue"><Activity size={13} /> {logs.length} events</Badge>} /><div className="audit-notice"><ShieldCheck size={18} /><div><b>Clinical activity is attributed to your account.</b><p>No passwords, access tokens or document contents are included in this log.</p></div></div><section className="panel audit-panel">{logs.length ? <div className="audit-list">{logs.map(log => { const grant = log.targetPatientId ? activeGrantFor(db, log.targetPatientId, currentUser.id) : undefined; return <div className="audit-row" key={log.id}><span className="audit-icon audit-record_view"><Activity size={15} /></span><div className="audit-description"><b>{actionLabels[log.action] || log.action.replace('_', ' ')}</b><p>{log.detail}</p><span>{log.targetPatientId ? grant ? `${fullName(db, log.targetPatientId)} · ${db.patients.find(p=>p.profileId===log.targetPatientId)?.patientId}` : 'Patient access no longer active' : 'Your account'} · {fmtDateTime(log.timestamp)}</span></div><Badge tone="blue">You</Badge></div> })}</div> : <EmptyState icon={<Activity size={23} />} title="No activity yet" description="Record access, requests and clinical notes will be logged here." />}</section><div className="fictional-notice"><Info size={14} /> This is not a production audit log. Demo events are stored locally in the browser.</div></div>
}
